"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type KeyboardEvent, type ReactNode, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One choice in a segmented control. */
export interface SegmentedControlOption<T extends string> {
  value: T;
  label: ReactNode;
  disabled?: boolean;
}

/** Props for a segmented control. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export interface SegmentedControlProps<T extends string> {
  options: SegmentedControlOption<T>[];
  value?: T;
  defaultValue?: T;
  onValueChange?: (value: T) => void;
  /** Names the group for screen readers, for example "Billing period". */
  "aria-label": string;
  className?: string;
}

// Critically damped: the indicator arrives fast and does not wobble, because
// the system is confirming a choice, not answering a throw.
const SPRING: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const STEP = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 } as const;

const isStepKey = (key: string): key is keyof typeof STEP => key in STEP;

/**
 * Picks one of a few options with a thumb that slides to the choice. It is a
 * radio group: Tab reaches the checked option, arrow keys move and select.
 */
export function SegmentedControl<T extends string>({
  options,
  value,
  defaultValue,
  onValueChange,
  "aria-label": ariaLabel,
  className,
}: SegmentedControlProps<T>) {
  const [ownValue, setOwnValue] = useState<T | undefined>(
    defaultValue ?? options.find((option) => !option.disabled)?.value,
  );
  const selected = value ?? ownValue;
  // Tab must always reach the group. If the chosen option is disabled or
  // missing, the first enabled option holds the tab stop instead.
  const enabled = options.filter((option) => !option.disabled);
  const tabStop = enabled.some((option) => option.value === selected) ? selected : enabled[0]?.value;
  const reduceMotion = useReducedMotion();
  // Each instance needs its own layout id, or two controls on one page would
  // pass a single thumb back and forth between them.
  const layoutId = useId();
  const buttons = useRef(new Map<T, HTMLButtonElement>());

  const select = (next: T) => {
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const current = enabled.findIndex((option) => option.value === selected);
    let index: number;
    if (event.key === "Home") index = 0;
    else if (event.key === "End") index = enabled.length - 1;
    else if (!isStepKey(event.key)) return;
    // From no enabled selection, a forward step lands on the first option and a backward step on the last.
    else if (current === -1) index = STEP[event.key] > 0 ? 0 : enabled.length - 1;
    else index = (current + STEP[event.key] + enabled.length) % enabled.length;

    event.preventDefault();
    const next = enabled[index];
    if (!next) return;
    buttons.current.get(next.value)?.focus();
    select(next.value);
  };

  return (
    <div
      role="radiogroup"
      aria-label={ariaLabel}
      onKeyDown={handleKeyDown}
      className={cn("inline-flex rounded-full bg-muted p-1", className)}
    >
      {options.map((option) => {
        const checked = option.value === selected;
        return (
          <button
            key={option.value}
            ref={(node) => {
              if (node) buttons.current.set(option.value, node);
              else buttons.current.delete(option.value);
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={option.value === tabStop ? 0 : -1}
            disabled={option.disabled}
            onClick={() => select(option.value)}
            className={cn(
              "group relative min-h-11 cursor-pointer touch-manipulation rounded-full px-4 text-sm font-medium outline-none motion-safe:transition-colors motion-safe:duration-200 sm:min-h-9",
              "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-muted",
              "disabled:cursor-not-allowed disabled:opacity-50",
              checked ? "text-foreground" : "text-muted-foreground hover:text-foreground",
            )}
          >
            {checked ? (
              <motion.span
                layoutId={layoutId}
                aria-hidden="true"
                transition={reduceMotion ? INSTANT : SPRING}
                className="absolute inset-0 rounded-full bg-background shadow-sm"
              />
            ) : null}
            <span className="relative inline-block motion-safe:transition-transform motion-safe:duration-150 group-active:scale-95">
              {option.label}
            </span>
          </button>
        );
      })}
    </div>
  );
}
